arguments.file_text:
@namespace sv_f07b095878374d4aada5c1607c01ebbf.Components.Pages.Apply

<div class="step-content">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@FullName" @onchange="e => FullName = e.Value?.ToString() ?? """ />
        @if (_errors.ContainsKey("FullName"))
        {
            <span class="error">@_errors["FullName"]</span>
        }
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Email" @onchange="e => Email = e.Value?.ToString() ?? """ />
        @if (_errors.ContainsKey("Email"))
        {
            <span class="error">@_errors["Email"]</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Phone" @onchange="e => Phone = e.Value?.ToString() ?? """ />
        @if (_errors.ContainsKey("Phone"))
        {
            <span class="error">@_errors["Phone"]</span>
        }
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Address" @onchange="e => Address = e.Value?.ToString() ?? """></textarea>
        @if (_errors.ContainsKey("Address"))
        {
            <span class="error">@_errors["Address"]</span>
        }
    </div>

    @if (_validatingEmail)
    {
        <p class="info">Validating email...</p>
    }

    <div class="step-actions">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@_validatingEmail">Next</button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private Dictionary<string, string> _errors = new();
    private bool _validatingEmail;

    private async Task HandleNext()
    {
        _errors.Clear();

        if (string.IsNullOrWhiteSpace(FullName)) _errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email)) _errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone)) _errors["Phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Address)) _errors["Address"] = "Address is required.";

        if (_errors.Count > 0) return;

        _validatingEmail = true;
        StateHasChanged();

        var isValid = await ApplicationService.ValidateEmailAsync(Email);
        _validatingEmail = false;

        if (!isValid)
        {
            _errors["Email"] = "Please enter a valid email address.";
            return;
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName, Email, Phone, Address));
    }
}

@namespace sv_f07b095878374d4aada5c1607c01ebbf.Components.Pages.Apply

<div class="step-content">
    <h3>Work History</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryEditor Entry="@Entries[index]"
                         Index="index"
                         ShowRemove="@(Entries.Count > 1)"
                         OnEntryChanged="e => UpdateEntry(index, e)"
                         OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_error))
    {
        <p class="error">@_error</p>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntry> Entries { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? _error;

    protected override void OnParametersSet()
    {
        if (Entries.Count == 0)
        {
            Entries = new List<WorkEntry> { new("", "", DateTime.Today, null, "") };
        }
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
        StateHasChanged();
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
            StateHasChanged();
        }
    }

    private void UpdateEntry(int index, WorkEntry updated)
    {
        Entries[index] = updated;
        StateHasChanged();
    }

    private async Task HandleNext()
    {
        _error = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _error = "Each position must have a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries);
    }
}

@namespace sv_f07b095878374d4aada5c1607c01ebbf.Components.Pages.Apply

<div class="step-content">
    <h3>References</h3>
    <p class="info">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];
        <div class="reference-card">
            <div class="entry-header">
                <h4>Reference @(index + 1)</h4>
                @if (References.Count > 2)
                {
                    <button type="button" class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>
            <div class="form-group">
                <label>Name *</label>
                <input type="text" value="@reference.Name"
                       @onchange="e => UpdateReference(index, reference with { Name = e.Value?.ToString() ?? "" })" />
            </div>
            <div class="form-group">
                <label>Relationship *</label>
                <input type="text" value="@reference.Relationship"
                       @onchange="e => UpdateReference(index, reference with { Relationship = e.Value?.ToString() ?? "" })" />
            </div>
            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" value="@reference.Email"
                           @onchange="e => UpdateReference(index, reference with { Email = e.Value?.ToString() ?? "" })" />
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" value="@reference.Phone"
                           @onchange="e => UpdateReference(index, reference with { Phone = e.Value?.ToString() ?? "" })" />
                </div>
            </div>
        </div>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(_error))
    {
        <p class="error">@_error</p>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? _error;

    protected override void OnParametersSet()
    {
        if (References.Count == 0)
        {
            References = new List<Reference>
            {
                new("", "", "", ""),
                new("", "", "", "")
            };
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference("", "", "", ""));
            StateHasChanged();
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
            StateHasChanged();
        }
    }

    private void UpdateReference(int index, Reference updated)
    {
        References[index] = updated;
        StateHasChanged();
    }

    private async Task HandleNext()
    {
        _error = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _error = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }
}

@namespace sv_f07b095878374d4aada5c1607c01ebbf.Components.Pages.Apply

<div class="step-content">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <label>Write your cover letter below:</label>
        <textarea rows="12" maxlength="2000" value="@CoverLetter"
                  @oninput="e => UpdateCoverLetter(e.Value?.ToString() ?? "")"></textarea>
        <span class="char-count">@CoverLetter.Length / 2000 characters</span>
    </div>

    @if (!string.IsNullOrEmpty(_error))
    {
        <p class="error">@_error</p>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnCoverLetterChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? _error;

    private void UpdateCoverLetter(string value)
    {
        CoverLetter = value.Length > 2000 ? value[..2000] : value;
        OnCoverLetterChanged.InvokeAsync(CoverLetter);
    }

    private async Task HandleNext()
    {
        _error = null;
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            _error = "Please write a cover letter.";
            return;
        }
        await OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_f07b095878374d4aada5c1607c01ebbf.Components.Pages.Apply

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (_submitted)
    {
        <div class="confirmation">
            <h4>&#10003; Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@_applicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="section-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="section-header">
                <h4>Work History</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in Work.Entries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <small>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
