@namespace sv_f07b095878374d4aada5c1607c01ebbf.Components.Pages.Apply

<div class="step-content">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@FullName" @onchange="e => FullName = e.Value?.ToString() ?? """ />
        @if (_errors.ContainsKey("FullName"))
        {
            <span class="error">@_errors["FullName"]</span>
        }
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Email" @onchange="e => Email = e.Value?.ToString() ?? """ />
        @if (_errors.ContainsKey("Email"))
        {
            <span class="error">@_errors["Email"]</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Phone" @onchange="e => Phone = e.Value?.ToString() ?? """ />
        @if (_errors.ContainsKey("Phone"))
        {
            <span class="error">@_errors["Phone"]</span>
        }
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Address" @onchange="e => Address = e.Value?.ToString() ?? """></textarea>
        @if (_errors.ContainsKey("Address"))
        {
            <span class="error">@_errors["Address"]</span>
        }
    </div>

    @if (_validatingEmail)
    {
        <p class="info">Validating email...</p>
    }

    <div class="step-actions">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@_validatingEmail">Next</button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private Dictionary<string, string> _errors = new();
    private bool _validatingEmail;

    private async Task HandleNext()
    {
        _errors.Clear();

        if (string.IsNullOrWhiteSpace(FullName)) _errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email)) _errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone)) _errors["Phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Address)) _errors["Address"] = "Address is required.";

        if (_errors.Count > 0) return;

        _validatingEmail = true;
        StateHasChanged();

        var isValid = await ApplicationService.ValidateEmailAsync(Email);
        _validatingEmail = false;

        if (!isValid)
        {
            _errors["Email"] = "Please enter a valid email address.";
            return;
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName, Email, Phone, Address));
    }
}

