<div class="step-content">
    <h3>References</h3>
    <p class="info">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];
        <div class="reference-card">
            <div class="entry-header">
                <h4>Reference @(index + 1)</h4>
                @if (References.Count > 2)
                {
                    <button type="button" class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>
            <div class="form-group">
                <label>Name *</label>
                <input type="text" value="@reference.Name"
                       @onchange="e => UpdateReference(index, reference with { Name = e.Value?.ToString() ?? "" })" />
            </div>
            <div class="form-group">
                <label>Relationship *</label>
                <input type="text" value="@reference.Relationship"
                       @onchange="e => UpdateReference(index, reference with { Relationship = e.Value?.ToString() ?? "" })" />
            </div>
            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" value="@reference.Email"
                           @onchange="e => UpdateReference(index, reference with { Email = e.Value?.ToString() ?? "" })" />
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" value="@reference.Phone"
                           @onchange="e => UpdateReference(index, reference with { Phone = e.Value?.ToString() ?? "" })" />
                </div>
            </div>
        </div>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(_error))
    {
        <p class="error">@_error</p>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? _error;

    protected override void OnParametersSet()
    {
        if (References.Count == 0)
        {
            References = new List<Reference>
            {
                new("", "", "", ""),
                new("", "", "", "")
            };
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference("", "", "", ""));
            StateHasChanged();
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
            StateHasChanged();
        }
    }

    private void UpdateReference(int index, Reference updated)
    {
        References[index] = updated;
        StateHasChanged();
    }

    private async Task HandleNext()
    {
        _error = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _error = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }
}

