@namespace sv_f07b095878374d4aada5c1607c01ebbf.Components.Pages.Apply

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (_submitted)
    {
        <div class="confirmation">
            <h4>&#10003; Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@_applicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="section-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="section-header">
                <h4>Work History</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in Work.Entries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <small>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="section-header">
                <h4>References</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-entry">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />
                    <small>@r.Email &bull; @r.Phone</small>
                </div>
            }
        </section>

        <section class="review-section">
            <div class="section-header">
                <h4>Cover Letter</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(_error))
        {
            <p class="error">@_error</p>
        }

        <div class="step-actions">
            <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@_submitting">
                @(_submitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Personal { get; set; } = default!;
    [Parameter, EditorRequired] public WorkHistory Work { get; set; } = default!;
    [Parameter, EditorRequired] public List<Reference> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private bool _submitting;
    private bool _submitted;
    private int _applicationId;
    private string? _error;

    private async Task HandleSubmit()
    {
        _submitting = true;
        _error = null;
        StateHasChanged();

        try
        {
            var application = new JobApplication(Personal, Work, References, CoverLetter);
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _error = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _submitting = false;
        }
    }
}

