@page "/apply"
@using sv_f07b095878374d4aada5c1607c01ebbf.Components.Pages.Apply
@using sv_f07b095878374d4aada5c1607c01ebbf.Models
@using sv_f07b095878374d4aada5c1607c01ebbf.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="_currentStep" OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                              ApplicationService="ApplicationService"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             OnNext="HandleWorkNext" OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="_references"
                            OnNext="HandleReferencesNext" OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             OnCoverLetterChanged="v => _coverLetter = v"
                             OnNext="HandleCoverLetterNext" OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@_personalInfo!" Work="@(new WorkHistory(_workEntries))"
                        References="_references" CoverLetter="@_coverLetter"
                        ApplicationService="ApplicationService"
                        OnEditStep="GoToStep" OnBack="GoBack" />
            break;
    }
</div>

@code {
    private int _currentStep;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private PersonalInfo? _personalInfo;

    // Step 2
    private List<WorkEntry> _workEntries = new() { new("", "", DateTime.Today, null, "") };

    // Step 3
    private List<Reference> _references = new() { new("", "", "", ""), new("", "", "", "") };

    // Step 4
    private string _coverLetter = "";

    private void HandlePersonalNext(PersonalInfo info)
    {
        _personalInfo = info;
        _fullName = info.FullName;
        _email = info.Email;
        _phone = info.Phone;
        _address = info.Address;
        _currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntry> entries)
    {
        _workEntries = entries;
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> references)
    {
        _references = references;
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _currentStep = 4;
    }

    private void GoToStep(int step)
    {
        if (step < _currentStep)
            _currentStep = step;
    }

    private void GoBack() => _currentStep = Math.Max(0, _currentStep - 1);
}

.application-form {
    max-width: 800px;
    margin: 2rem auto;
    padding: 1.5rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: default;
    padding: 0.5rem;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-number {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.875rem;
    margin-bottom: 0.25rem;
    border: 2px solid #ccc;
    color: #999;
}

.step.active .step-number {
    border-color: #0d6efd;
    background: #0d6efd;
    color: white;
}

.step.completed .step-number {
    border-color: #198754;
    background: #198754;
    color: white;
}

.step.future .step-number {
    border-color: #dee2e6;
    color: #adb5bd;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.future .step-label {
    color: #adb5bd;
}

.step-connector {
    width: 30px;
    height: 2px;
    background: #dee2e6;
    margin-bottom: 1rem;
}

.step-connector.completed {
    background: #198754;
}

.checkmark {
    font-size: 1rem;
}

/* Form Elements */
.step-content {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 1.5rem;
}

.step-content h3 {
    margin-top: 0;
    margin-bottom: 1rem;
    color: #333;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    font-size: 0.875rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.9rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.form-row .form-group {
    flex: 1;
    min-width: 150px;
}

.checkbox-group {
    display: flex;
    align-items: center;
    padding-top: 1.5rem;
}

.checkbox-group label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal;
}

/* Buttons */
.step-actions {
    display: flex;
    gap: 1rem;
    margin-top: 1.5rem;
    justify-content: flex-end;
}

.btn-primary {
    background: #0d6efd;
    color: white;
    border: none;
    padding: 0.5rem 1.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-primary:disabled {
    background: #6c9ce6;
    cursor: not-allowed;
}

.btn-outline {
    background: white;
    color: #0d6efd;
    border: 1px solid #0d6efd;
    padding: 0.5rem 1.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-outline:hover {
    background: #f0f7ff;
}

.btn-secondary {
    background: #6c757d;
    color: white;
    border: none;
    padding: 0.4rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
    margin-top: 0.5rem;
}

.btn-secondary:hover {
    background: #5a6268;
}

.btn-remove {
    background: none;
    border: none;
    color: #dc3545;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-remove:hover {
    text-decoration: underline;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.85rem;
    text-decoration: underline;
}

.btn-submit {
    padding: 0.6rem 2rem;
    font-size: 1rem;
}

/* Errors and Info */
.error {
    color: #dc3545;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    display: block;
}

.info {
    color: #6c757d;
    font-size: 0.85rem;
}

.char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

/* Work Entry & Reference Cards */
.work-entry-editor,
.reference-card {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.entry-header h4 {
    margin: 0;
    font-size: 0.95rem;
}

/* Review Step */
.review-section {
    border-bottom: 1px solid #e9ecef;
    padding-bottom: 1rem;
    margin-bottom: 1rem;
}

.review-section:last-of-type {
    border-bottom: none;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.section-header h4 {
    margin: 0 0 0.5rem 0;
}

.review-section dl {
    display: grid;
    grid-template-columns: 100px 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
    font-size: 0.85rem;
    color: #555;
}

.review-section dd {
    margin: 0;
    font-size: 0.9rem;
}

.review-entry {
    margin-bottom: 0.75rem;
    padding-left: 0.5rem;
    border-left: 3px solid #dee2e6;
}

.review-entry p {
    margin: 0.25rem 0 0 0;
    font-size: 0.85rem;
    color: #555;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 0.75rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation h4 {
    color: #198754;
    font-size: 1.5rem;
}

