@namespace sv_f07b095878374d4aada5c1607c01ebbf.Components.Pages.ApplySteps

<div class="work-entry-editor">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company"
               @onchange="e => Update(Entry with { Company = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title"
               @onchange="e => Update(Entry with { Title = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@FormatDate(Entry.StartDate)"
                   @onchange="e => Update(Entry with { StartDate = ParseDate(e.Value) })" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@FormatNullableDate(Entry.EndDate)"
                   disabled="@IsCurrent"
                   @onchange="e => Update(Entry with { EndDate = ParseNullableDate(e.Value) })" />
        </div>
        <div class="form-group checkbox-group">
            <label>
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                Current position
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => Update(Entry with { Description = e.Value?.ToString() ?? string.Empty })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate == null && Entry.StartDate != default;

    private void Update(WorkEntry updated) => OnEntryChanged.InvokeAsync(updated);

    private void ToggleCurrent(bool isCurrent)
    {
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        Update(updated);
    }

    private static string FormatDate(DateTime date) => date.ToString("yyyy-MM-dd");
    private static string FormatNullableDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? string.Empty;
    private static DateTime ParseDate(object? value) => DateTime.TryParse(value?.ToString(), out var d) ? d : DateTime.Today;
    private static DateTime? ParseNullableDate(object? value) => DateTime.TryParse(value?.ToString(), out var d) ? d : null;
}

